public static byte[] UTF8GetFixLenBytes(string str, int len)
{
	if (str == null)
	{
		return null;
	}
	byte[] array = new byte[len];
	byte[] bytes = Encoding.UTF8.GetBytes(str);
	Buffer.BlockCopy(bytes, 0, array, 0, Math.Min(bytes.Length, len));
	return array;
}

